import{z as l,x as B,o as E,c as p,q as i,j as s,D as r,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"感知器预测器","description":"","frontmatter":{"title":"感知器预测器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/perceptron-predictor.md","filePath":"cs/perceptron-predictor.md","lastUpdated":1791413859000}'),d={name:"cs/perceptron-predictor.md"};function D(h,a,m,c,T,P){const n=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=i('<h1 id="感知器预测器" tabindex="-1">感知器预测器 <a class="header-anchor" href="#感知器预测器" aria-label="Permalink to &quot;感知器预测器&quot;">​</a></h1><div class="epigraph"><p>把全局历史的每一位当成特征，用一组权重做点积；阈值为正猜跳、为负猜不跳，训错则按历史加减权重。</p><footer>—— 据 Jiménez and Lin, Dynamic Branch Prediction with Perceptrons, HPCA 2001 整理</footer></div><p><a href="/cs/tage-predictor">上一课</a>用若干张表记住「这一段历史出现过」。历史是索引，不是特征：两位计数器无法表达「第 3 位与第 17 位同时为 1 才跳」这种可加结构。本课不重讲几何标签。缺口是：<strong>把 GHR 当成向量，用感知器做线性判别</strong>，专打 TAGE 也难压缩的线性相关。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有一类分支：方向近似于若干个更早分支的异或或加权和（编译器展开后的复合条件）。PHT 要把每种 0/1 模式各占一项才能学会；历史一长，项数 \\(2^h\\)。若真实分界面近似超平面，用 \\(h\\) 个权重就够。缺口不是再加一张更长的 TAGE 表，而是<strong>点积 + 在线训练</strong>。</p><p><span class="marginnote">「线性判别」就是用一条直线（高维里叫超平面）把「跳」「不跳」两类历史模式划开。数字感受一下容量差距：\\(h=40\\) 时 PHT 需要 \\(2^{40}\\) 项（约一万亿），感知器只要 41 个权重——每个历史位一个，再加一个偏置。</span></p><p>Jiménez 与 Lin 借用 Rosenblatt 感知器：输入是 GHR 各位（及常数偏置），输出符号即方向。它不是多层网络，本课不把它写成深度学习。</p><p><span class="marginnote">训练规则：预测错，或点积绝对值小于饱和阈值时，对每个 \\(x_i=1\\) 的权重向正确方向加一，对 \\(x_i=0\\) 减一。权重有界以防溢出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按 PC 选一行权重 \\(\\mathbf{w}\\)（可多表散列）。计算 \\(y = w_0 + \\sum_i w_i x_i\\)，其中 \\(x_i\\in\\{+1,-1\\}\\) 来自 GHR。\\(y\\ge 0\\) 预测成功。核对后按上述规则更新该行。为实现，点积可在移位 GHR 时用加减累加，不必每拍做 \\(h\\) 次乘。</p>',10)),(E(),s(A,null,{default:r(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20GHR%5B%22GHR%20%E5%90%84%E4%BD%8D%22%5D%20--%3E%20DOT%5B%22%E4%B8%8E%E6%9D%83%E9%87%8D%E7%82%B9%E7%A7%AF%22%5D%0A%20%20W%5B%22%E6%8C%89%20PC%20%E9%80%89%E6%9D%83%E9%87%8D%E8%A1%8C%22%5D%20--%3E%20DOT%0A%20%20DOT%20--%3E%20SIGN%5B%22%E7%AC%A6%E5%8F%B7%E5%8D%B3%E6%96%B9%E5%90%91%22%5D%0A%20%20SIGN%20--%3E%20CHK%5B%22%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%20UPD%5B%22%E6%8C%89%E8%AF%AF%E5%B7%AE%E6%9B%B4%E6%96%B0%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 gshare/TAGE 可竞赛：选择器看谁最近更准。感知器擅长线性可分，TAGE 擅长不规则模式；互补正是 McFarling 锦标赛那一套，只是一路换成权重。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"可以把它想象成加权表决：每个历史位是一位评委，与该分支相关性强的评委票权大、没关系的票权接近零，\\(y\\) 就是总票数，为正即通过（预测跳）。所谓训练，就是每次投错了调一调各位评委的票权。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"CPI 公式不变，改的是误预测率的来源：线性分支不再吃指数级 PHT。代价是每拍点积的延迟与权重 SRAM 端口。历史越长，关键路径越差，这与 TAGE 用几何表换索引延迟是另一笔交易。",-1)),(E(),s(A,null,{default:r(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20PHTW%5B%22PHT%20%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20%20%20A1%5B%22%E5%8E%86%E5%8F%B2%E9%95%BF%20h%20%E4%BD%8D%22%5D%20--%3E%20A2%5B%22%E7%B4%A2%E5%BC%95%E4%B8%80%E5%BC%A0%202%5Eh%20%E9%A1%B9%E7%9A%84%E8%A1%A8%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E6%AF%8F%E7%A7%8D%200%2F1%20%E6%A8%A1%E5%BC%8F%E5%90%84%E8%87%AA%E8%AE%B0%E4%B8%80%E7%A5%A8%22%5D%0A%20%20end%0A%20%20subgraph%20PERC%5B%22%E6%84%9F%E7%9F%A5%E5%99%A8%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20%20%20B1%5B%22%E5%8E%86%E5%8F%B2%E9%95%BF%20h%20%E4%BD%8D%22%5D%20--%3E%20B2%5B%22%E6%9D%83%E9%87%8D%E5%8F%AA%E6%9C%89%20h%2B1%20%E4%B8%AA%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%82%B9%E7%A7%AF%E5%AD%A6%E5%87%BA%E4%BD%8D%E9%97%B4%E7%9A%84%E7%BA%BF%E6%80%A7%E5%85%B3%E7%B3%BB%22%5D%0A%20%20end%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>权重行同样会被别名：不同 PC 散列到同一行会互相拆台，可用部分标签或更细散列缓解，思想同 TAGE，本课不另开一张几何权重表。</p><p><span class="marginnote">常见误区：一听「感知器」就想到神经网络和 GPU 训练——它只有一个神经元，更新只是整数加减一，硬件里一个加法器就够。真正的坑是别名：两个分支共用一行权重时互相污染，表现为这条分支越跑越不准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把多层感知器、也不把神经网络分支预测器铺开。间接目标不能用正负号表示，仍走 BTB / 后课间接预测。训练必须在核对后（或可回滚），推测更新会污染权重。</p><p>后课默认：方向预测有三条成熟路——饱和表、TAGE、感知器。目标地址仍可能每次不同，那是下一课间接分支。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>感知器用 GHR 特征做线性判别，项数随 \\(h\\) 线性而非 \\(2^h\\)。</li><li>与 TAGE 互补：不规则模式仍靠带标签的表。</li><li>间接跳转的目标集合是下一课的缺口。</li><li>出处：Jiménez and Lin, <em>HPCA</em>, 2001。</li></ul>',7))])}const f=l(d,[["render",D]]);export{u as __pageData,f as default};
